
/* ---- Hosted runtime: replaces the claude.ai capabilities with this app's own API ---- */
(function(){
  const toSignin = () => { window.location.href = "/signin"; };
  async function api(url, opts){
    const r = await fetch(url, Object.assign({credentials:"same-origin"}, opts||{}));
    if(r.status === 401){ toSignin(); throw {code:"unauthenticated", message:"Signed out"}; }
    if(!r.ok){ let m = "Request failed"; try{ m = (await r.json()).error || m; }catch{} throw {code:"unavailable", message:m}; }
    return r.json();
  }
  const listeners = []; let last = ""; let timer = null;
  function toSnap(rows){ return { docs: rows.map(r=>({ id:r.id, data:()=>({ name:r.name, order:r.order, fields:r.fields||{}, logo:r.logo||null }) })) }; }
  async function poll(force){
    try{
      const rows = await api("/api/profiles", {cache:"no-store"});
      const s = JSON.stringify(rows);
      if(force || s !== last){ last = s; const snap = toSnap(rows); listeners.forEach(l=>l.next(snap)); }
    }catch(e){ if(e && e.code==="unauthenticated") return; }
  }
  function schedule(){ clearTimeout(timer); timer = setTimeout(async()=>{ if(!document.hidden) await poll(); schedule(); }, 5000); }
  document.addEventListener("visibilitychange", ()=>{ if(!document.hidden) poll(); });
  const db = {
    collection(){ return { onSnapshot(next, error){ listeners.push({next, error}); poll(true); schedule(); return ()=>{}; } }; },
    doc(path){
      const id = path.split("/")[1];
      return { async update(u){
        if(u.fields){ for(const [field, value] of Object.entries(u.fields)){
          await api("/api/profiles/"+encodeURIComponent(id), {method:"PATCH", headers:{"Content-Type":"application/json"}, body:JSON.stringify({field, value})}); } }
        if("logo" in u){ await api("/api/profiles/"+encodeURIComponent(id), {method:"PATCH", headers:{"Content-Type":"application/json"}, body:JSON.stringify({logo:u.logo})}); }
        poll();
      } };
    }
  };
  const downloads = { async save({filename, data}){
    const blob = data instanceof Blob ? data : new Blob([data]);
    const a = document.createElement("a"); a.href = URL.createObjectURL(blob); a.download = filename;
    document.body.appendChild(a); a.click(); setTimeout(()=>{ URL.revokeObjectURL(a.href); a.remove(); }, 1000);
    return {status:"saved"};
  } };
  const assets = { async upload(file){
    const fd = new FormData(); fd.append("file", file);
    const res = await api("/api/logo", {method:"POST", body:fd});
    return { id: res.url, url: res.url };
  } };
  window.claude = { use: async (name)=> ({db, downloads, assets})[name] || null };
})();

const ICONS = {"facebook": "data:image/png;base64,", "instagram": "data:image/png;base64,", "linkedin": "data:image/png;base64,", "pinterest": "data:image/png;base64,", "youtube": "data:image/png;base64,", "gbp": "data:image/png;base64,", "yelp": "data:image/png;base64,", "bbb": "data:image/png;base64,", "tiktok": "data:image/png;base64,"};
const PLATFORMS = [
  {id:"website", label:"Dealership website", fields:[{k:"website", lim:1000}]},
  {id:"facebook", label:"Facebook", fields:[{k:"facebook", lim:255}]},
  {id:"instagram", label:"Instagram", fields:[{k:"instagram", lim:150}]},
  {id:"tiktok", label:"TikTok", fields:[{k:"tiktok", lim:80}]},
  {id:"pinterest", label:"Pinterest", fields:[{k:"pinterest", lim:160}]},
  {id:"linkedin", label:"LinkedIn", fields:[{k:"linkedin", sub:"Tagline", lim:220},{k:"linkedinOverview", sub:"Overview", lim:2000}]},
  {id:"gbp", label:"Google Business Profile", fields:[{k:"gbp", lim:750}]},
  {id:"youtube", label:"YouTube", fields:[{k:"youtube", lim:1000}]},
  {id:"yelp", label:"Yelp", fields:[{k:"yelpSpecialties", sub:"Specialties", lim:1500},{k:"yelpHistory", sub:"History", lim:1000}]},
  {id:"bbb", label:"Better Business Bureau", note:"Business overview for your bbb.org profile. Leave out superiority claims and promotions.", fields:[{k:"bbb", lim:900}]},
];
const FIELDS = PLATFORMS.flatMap(pl=>pl.fields.map(f=>({...f, pid:pl.id, label: f.sub ? pl.label+" "+f.sub.toLowerCase() : pl.label})));
const FMAP = Object.fromEntries(FIELDS.map(f=>[f.k,f]));
const len = s => [...(s||"")].length;

const st = { view:"platform", dealer:null, platform:"website", profiles:[], byId:{}, q:"" };
const pending = {};   // "id|field" -> timer
const localVal = {};  // "id|field" -> text not yet confirmed
let db = null, downloads = null, assets = null, readOnly = false;
const PMAP = Object.fromEntries(PLATFORMS.map(p=>[p.id,p]));

const $ = s => document.querySelector(s);
const esc = s => String(s).replace(/[&<>"]/g, c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));

function val(p, k){ const lk = p.id+"|"+k; return lk in localVal ? localVal[lk] : ((p.fields||{})[k] || ""); }
function flags(text, f){ return { over: len(text) > f.lim }; }
function counts(p){ let o=0,n=0; for(const f of FIELDS){ const x=flags(val(p,f.k),f); if(x.over)o++; if(x.need)n++; } return {o,n}; }
function platCounts(pid){ let o=0,n=0; for(const f of PMAP[pid].fields) for(const p of st.profiles){ const x=flags(val(p,f.k),f); if(x.over)o++; if(x.need)n++; } return {o,n}; }
function pips(c){ return (c.o?`<span class="pip o" title="${c.o} over limit">${c.o}</span>`:""); }

function logoURL(p){ return p && p.logo ? p.logo : ""; }
function iconHTML(pid, p){
  if(pid==="website"){ const u=logoURL(p); return u ? `<img class="ico" src="${esc(u)}" alt="">` : `<span class="ico ico-web" aria-hidden="true">www</span>`; }
  if(ICONS[pid]) return `<img class="ico" src="${ICONS[pid]}" alt="">`;
  return `<span class="ico ico-txt" aria-hidden="true">TT</span>`;
}
function renderTally(){
  let o=0,n=0; for(const p of st.profiles){ const c=counts(p); o+=c.o; n+=c.n; }
  $("#tally").innerHTML = `<span class="t-over"><b>${o}</b> over limit</span>`;
}

function renderRail(){
  const ul = $("#railList"); const q = st.q.trim().toLowerCase();
  $(".rail-head").style.display = st.view==="dealer" ? "" : "none";
  let items;
  if(st.view==="dealer"){
    items = st.profiles.filter(p=>!q || p.name.toLowerCase().includes(q)).map(p=>
      `<li><button type="button" data-id="${esc(p.id)}" aria-current="${p.id===st.dealer}"><span class="nm">${esc(p.name)}</span>${pips(counts(p))}</button></li>`);
  } else {
    items = PLATFORMS.map(pl=>`<li><button type="button" data-k="${pl.id}" aria-current="${pl.id===st.platform}">${iconHTML(pl.id, null)}<span class="nm">${esc(pl.label)}</span>${pips(platCounts(pl.id))}</button></li>`);
  }
  ul.innerHTML = items.join("") || `<li style="padding:10px;color:var(--muted);font-size:14px">No dealership matches “${esc(st.q)}”.</li>`;
}

function fieldHTML(p, f, head){
  const t = val(p, f.k), L = len(t);
  const lab = head
    ? `${head.icon}<label class="f-label f-label-main" for="ta-${esc(p.id)}-${f.k}">${esc(head.title)}<small>${f.lim.toLocaleString()} characters</small></label>`
    : `<label class="f-label" for="ta-${esc(p.id)}-${f.k}"><b>${esc(f.sub||"")}</b><small>${f.lim.toLocaleString()} characters</small></label>`;
  return `<div class="field" data-id="${esc(p.id)}" data-k="${f.k}">
    <div class="f-top">${lab}
      <span class="count">${L.toLocaleString()} / ${f.lim.toLocaleString()}</span>
      <button class="btn" type="button" data-copy>Copy</button>
    </div>
    ${head && head.note ? head.note : ""}
    <textarea id="ta-${esc(p.id)}-${f.k}" rows="2" ${readOnly?"readonly":""} spellcheck="true">${esc(t)}</textarea>
    <div class="f-foot">${footHTML(t,f)}<span class="save" data-save></span></div>
  </div>`;
}
function cardClass(p, pl){ let o=false,n=false; for(const f of pl.fields){ const x=flags(val(p,f.k),f); o=o||x.over; n=n||x.need; } return (o?" is-over":"")+(n?" is-need":""); }
function cardHTML(p, pl, title, icon){
  const note = pl.note ? `<p class="c-note">${esc(pl.note)}</p>` : "";
  const inner = pl.fields.length===1
    ? fieldHTML(p, pl.fields[0], {icon, title, note})
    : `<div class="c-head">${icon}<h3>${esc(title)}</h3></div>${note}${pl.fields.map(f=>fieldHTML(p,f)).join("")}`;
  return `<section class="card${cardClass(p,pl)}">${inner}</section>`;
}
function footHTML(t, f){
  const x = flags(t,f); let h="";
  if(x.over) h += `<span class="flag o">Over by ${(len(t)-f.lim).toLocaleString()}</span>`;
  return `<span data-flags style="display:contents">${h}</span>`;
}

function renderMain(){
  const m = $("#main");
  if(!st.profiles.length){ return; }
  if(st.view==="dealer"){
    const p = st.byId[st.dealer] || st.profiles[0]; st.dealer = p.id;
    const u = logoURL(p);
    let html = `<select class="rail-select" id="mSelect" aria-label="Dealership">${st.profiles.map(x=>`<option value="${esc(x.id)}" ${x.id===p.id?"selected":""}>${esc(x.name)}</option>`).join("")}</select>
      <div class="head"><div>${u?`<img class="head-logo" src="${esc(u)}" alt="${esc(p.name)} logo">`:""}<h1>${esc(p.name)}</h1><p>Every platform bio for this profile. Edits save for everyone.</p></div>
      <div class="head-actions">${assets?`<button class="btn logo-btn" type="button" id="logoBtn">${u?"Change logo":"Add logo"}</button><input type="file" id="logoFile" accept="image/png,image/jpeg,image/webp,image/svg+xml" hidden>`:""}
      <button class="btn btn-cta" type="button" id="copyAll">Copy all platforms</button></div></div>`;
    for(const pl of PLATFORMS) html += cardHTML(p, pl, pl.label, iconHTML(pl.id, p));
    m.innerHTML = html;
  } else {
    const pl = PMAP[st.platform];
    let html = `<select class="rail-select" id="mSelect" aria-label="Platform">${PLATFORMS.map(x=>`<option value="${x.id}" ${x.id===pl.id?"selected":""}>${esc(x.label)}</option>`).join("")}</select>
      <div class="head"><div><h1>${esc(pl.label)}</h1><p>${pl.fields.map(f=>(f.sub?f.sub+": ":"")+f.lim.toLocaleString()+" characters").join(" · ")}, across all ${st.profiles.length} profiles.</p></div>
      <button class="btn btn-cta" type="button" id="copyAll">Copy all dealerships</button></div>`;
    for(const p of st.profiles){ const u=logoURL(p); html += cardHTML(p, pl, p.name, u?`<img class="ico" src="${esc(u)}" alt="">`:""); }
    m.innerHTML = html;
  }
  m.querySelectorAll("textarea").forEach(autosize);
}
function autosize(ta){ ta.style.height="auto"; ta.style.height = (ta.scrollHeight+2)+"px"; }

function refreshField(sec){
  const p = st.byId[sec.dataset.id], f = FMAP[sec.dataset.k], t = val(p, f.k), x = flags(t,f);
  sec.classList.toggle("is-over", x.over); sec.classList.toggle("is-need", x.need);
  sec.querySelector(".count").textContent = `${len(t).toLocaleString()} / ${f.lim.toLocaleString()}`;
  sec.querySelector("[data-flags]").outerHTML = footHTML(t,f);
  const card = sec.closest(".card"); if(card){ const pl = PMAP[f.pid]; card.className = "card"+cardClass(p, pl); }
}

/* Live updates from other editors: patch values in place, never clobber a field being edited */
function applySnapshot(docs){
  const prevCount = st.profiles.length;
  st.profiles = docs.map(d=>({id:d.id, ...d.data()})).sort((a,b)=>(a.order??999)-(b.order??999) || a.name.localeCompare(b.name));
  st.byId = Object.fromEntries(st.profiles.map(p=>[p.id,p]));
  if(!st.dealer || !st.byId[st.dealer]) st.dealer = st.profiles[0]?.id;
  if(!st.profiles.length){
    $("#main").innerHTML = `<div class="empty"><h2>No profiles yet</h2><p>The dealership list hasn't been loaded into this page.</p></div>`;
    renderRail(); renderTally(); return;
  }
  const logoSig = st.profiles.map(p=>p.logo||"").join("|");
  if(!prevCount || !$("#main .field") || logoSig!==st._logoSig){ st._logoSig = logoSig; if(!document.activeElement || document.activeElement.tagName!=="TEXTAREA" || !prevCount) { renderMain(); } }
  else {
    document.querySelectorAll("#main .field").forEach(sec=>{
      const lk = sec.dataset.id+"|"+sec.dataset.k, ta = sec.querySelector("textarea");
      if(lk in localVal || document.activeElement===ta) return;
      const t = val(st.byId[sec.dataset.id], sec.dataset.k);
      if(ta.value !== t){ ta.value = t; autosize(ta); }
      refreshField(sec);
    });
  }
  renderRail(); renderTally();
}

function queueSave(id, k, text, sec){
  const lk = id+"|"+k; localVal[lk] = text;
  const s = sec.querySelector("[data-save]"); s.className="save"; s.textContent="Editing…";
  clearTimeout(pending[lk]);
  pending[lk] = setTimeout(()=>flush(id,k,sec), 700);
}
const inflight = {};
async function flush(id, k, sec){
  const lk = id+"|"+k; clearTimeout(pending[lk]); delete pending[lk];
  if(!(lk in localVal)) return;
  if(inflight[id]) { await inflight[id]; }
  const text = localVal[lk];
  const s = sec && sec.isConnected ? sec.querySelector("[data-save]") : null;
  if(s){ s.className="save"; s.textContent="Saving…"; }
  const job = db.doc("profiles/"+id).update({fields:{[k]:text}});
  inflight[id] = job.catch(()=>{});
  try{
    await job;
    if(localVal[lk]===text) delete localVal[lk];
    if(s && s.isConnected){ s.textContent="Saved"; setTimeout(()=>{ if(s.textContent==="Saved") s.textContent=""; }, 1800); }
  }catch(e){
    if(s && s.isConnected){ s.className="save err";
      s.textContent = e && e.code==="invalid_argument" ? "You have view-only access, so this edit wasn't saved." : "Couldn't save. Your text is still here; keep typing to try again."; }
  } finally { delete inflight[id]; }
}

/* Clipboard with fallback for framed pages */
async function copyText(t){
  try{ await navigator.clipboard.writeText(t); return true; }
  catch{ const a=document.createElement("textarea"); a.value=t; a.style.position="fixed"; a.style.opacity="0";
    document.body.appendChild(a); a.select(); let ok=false; try{ ok=document.execCommand("copy"); }catch{} a.remove(); return ok; }
}
let toastT; function toast(msg){ const t=$("#toast"); t.textContent=msg; t.classList.add("show"); clearTimeout(toastT); toastT=setTimeout(()=>t.classList.remove("show"),1800); }

function copyAllText(){
  if(st.view==="dealer"){
    const p = st.byId[st.dealer];
    return p.name+"\n\n"+FIELDS.map(f=>`${f.label} (${f.lim.toLocaleString()} characters)\n${val(p,f.k)}`).join("\n\n");
  }
  const pl = PMAP[st.platform];
  return `${pl.label}\n\n`+st.profiles.map(p=>p.name+"\n"+pl.fields.map(f=>(f.sub?f.sub+"\n":"")+val(p,f.k)).join("\n\n")).join("\n\n\n");
}

/* Export */
function rows(){
  const head = ["Dealership", ...FIELDS.flatMap(f=>[`${f.label} (${f.lim})`, `${f.label} count`])];
  return [head, ...st.profiles.map(p=>[p.name, ...FIELDS.flatMap(f=>{ const t=val(p,f.k); return [t, len(t)]; })])];
}
function toCSV(r){ return "\ufeff"+r.map(row=>row.map(c=>{ const s=String(c); return /[",\n\r]/.test(s) ? '"'+s.replace(/"/g,'""')+'"' : s; }).join(",")).join("\r\n"); }
async function doExport(fmt){
  const stamp = new Date().toISOString().slice(0,10);
  try{
    if(fmt==="csv"){ await downloads.save({filename:`garber-profile-copy-${stamp}.csv`, data:toCSV(rows())}); }
    else {
      if(!window.XLSX){ toast("Excel export didn't load. Try CSV."); return; }
      const ws = XLSX.utils.aoa_to_sheet(rows());
      ws["!cols"] = [{wch:34}, ...FIELDS.flatMap(()=>[{wch:60},{wch:10}])];
      const wb = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(wb, ws, "Profile copy");
      const out = XLSX.write(wb, {type:"array", bookType:"xlsx"});
      await downloads.save({filename:`garber-profile-copy-${stamp}.xlsx`, data:new Uint8Array(out)});
    }
    toast("Export saved");
  }catch(e){
    if(e && e.code==="declined") return;
    toast(e && e.code==="rate_limited" ? "A save prompt is already open." : "Export isn't available here.");
  }
}

/* Events */
document.querySelector(".seg").addEventListener("click", e=>{
  const b = e.target.closest("button[data-view]"); if(!b) return;
  st.view = b.dataset.view;
  document.querySelectorAll(".seg button").forEach(x=>x.setAttribute("aria-pressed", x===b));
  renderRail(); renderMain(); window.scrollTo(0,0);
});
$("#railList").addEventListener("click", e=>{
  const b = e.target.closest("button"); if(!b) return;
  if(b.dataset.id) st.dealer = b.dataset.id; else st.platform = b.dataset.k;
  renderRail(); renderMain(); window.scrollTo(0,0);
});
$("#search").addEventListener("input", e=>{ st.q = e.target.value; renderRail(); });
$("#main").addEventListener("change", e=>{
  if(e.target.id!=="mSelect") return;
  if(st.view==="dealer") st.dealer = e.target.value; else st.platform = e.target.value;
  renderRail(); renderMain();
});
$("#main").addEventListener("input", e=>{
  const ta = e.target; if(ta.tagName!=="TEXTAREA" || readOnly) return;
  const sec = ta.closest(".field"); autosize(ta);
  queueSave(sec.dataset.id, sec.dataset.k, ta.value, sec);
  refreshField(sec); renderTally(); renderRail();
});
$("#main").addEventListener("focusout", e=>{
  const ta = e.target; if(ta.tagName!=="TEXTAREA") return;
  const sec = ta.closest(".field"), lk = sec.dataset.id+"|"+sec.dataset.k;
  if(pending[lk]) flush(sec.dataset.id, sec.dataset.k, sec);
});
$("#main").addEventListener("click", async e=>{
  if(e.target.closest("[data-copy]")){
    const sec = e.target.closest(".field");
    const ok = await copyText(val(st.byId[sec.dataset.id], sec.dataset.k));
    toast(ok ? "Copied" : "Couldn't copy. Select the text and copy it manually.");
  } else if(e.target.id==="logoBtn"){
    $("#logoFile").click();
  } else if(e.target.id==="copyAll"){
    const ok = await copyText(copyAllText());
    toast(ok ? (st.view==="dealer" ? "Copied all 10 platforms" : "Copied all dealerships") : "Couldn't copy.");
  }
});
$("#main").addEventListener("change", async e=>{
  if(e.target.id!=="logoFile" || !e.target.files[0]) return;
  const file = e.target.files[0], id = st.dealer, btn = $("#logoBtn");
  if(btn){ btn.disabled = true; btn.textContent = "Uploading…"; }
  try{
    const res = await assets.upload(file);
    await db.doc("profiles/"+id).update({logo: res.id});
    toast("Logo added");
  }catch(err){
    toast("Couldn't upload that logo. Use a PNG, JPG, WebP, or SVG under 2 MB.");
    if(btn){ btn.disabled = false; btn.textContent = logoURL(st.byId[id]) ? "Change logo" : "Add logo"; }
  }
});
$("#exportBtn").addEventListener("click", ()=>{ const l=$("#exportList"); const o=!l.classList.contains("open"); l.classList.toggle("open",o); $("#exportBtn").setAttribute("aria-expanded",o); });
$("#exportList").addEventListener("click", e=>{ const b=e.target.closest("button[data-fmt]"); if(!b) return; $("#exportList").classList.remove("open"); doExport(b.dataset.fmt); });
document.addEventListener("click", e=>{ if(!e.target.closest("#exportMenu")) $("#exportList").classList.remove("open"); });
window.addEventListener("beforeunload", e=>{ if(Object.keys(pending).length){ e.preventDefault(); e.returnValue=""; } });

/* Boot */
(async ()=>{
  const c = window.claude;
  db = c && c.use ? await c.use("db") : null;
  if(!db){
    $("#main").innerHTML = `<div class="empty"><h2>Shared copy isn't available here</h2><p>Open this page from its claude.ai link while signed in to load and edit the dealership bios.</p></div>`;
    return;
  }
  try{ const u = await c.use("user"); if(u && u.can){ const w = await u.can("data.write"); if(w===false) readOnly = true; } }catch{}
  downloads = await c.use("downloads");
  try{ assets = await c.use("assets"); }catch{ assets = null; }
  if(downloads) $("#exportMenu").hidden = false;
  db.collection("profiles").onSnapshot(snap=>applySnapshot(snap.docs), err=>{
    $("#main").innerHTML = `<div class="empty"><h2>Lost connection to the shared copy</h2><p>Reload the page to reconnect. Anything not marked "Saved" may need to be retyped.</p></div>`;
  });
})();

/* Sign out without leaving for the default auth page */
document.getElementById("signOut")?.addEventListener("click", async (e) => {
  e.preventDefault();
  try {
    const { csrfToken } = await (await fetch("/api/auth/csrf")).json();
    const f = document.createElement("form");
    f.method = "POST"; f.action = "/api/auth/signout";
    for (const [k, v] of Object.entries({ csrfToken, callbackUrl: "/signin" })) {
      const i = document.createElement("input"); i.type = "hidden"; i.name = k; i.value = v; f.appendChild(i);
    }
    document.body.appendChild(f); f.submit();
  } catch { window.location.href = "/api/auth/signout"; }
});
